solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <cstring>
#include <mutex>
#include <vector>

struct Event { std::uint64_t seq; std::uint64_t time; std::uint32_t pid; std::uint32_t kind; };

class EventRing
{
public:
    explicit EventRing(std::size_t capacity) : m_slots(capacity) {}

    std::uint64_t push(std::uint64_t time, std::uint32_t pid, std::uint32_t kind)
    {
        std::lock_guard<std::mutex> lock{ m_lock };
        const std::uint64_t seq{ ++m_lastSeq };
        m_slots[m_next] = { seq, time, pid, kind };
        m_next = (m_next + 1) % m_slots.size();
        if (m_count < m_slots.size()) ++m_count;
        else ++m_overwritten;
        return seq;
    }

    std::size_t size() const { std::lock_guard<std::mutex> lock{ m_lock }; return m_count; }
    std::uint64_t overwritten() const { std::lock_guard<std::mutex> lock{ m_lock }; return m_overwritten; }

    std::vector<Event> read(std::uint64_t afterSeq, std::size_t maxCount, std::uint64_t& missed) const
    {
        std::lock_guard<std::mutex> lock{ m_lock };
        return readLocked(afterSeq, maxCount, missed);
    }

    std::uint32_t serialize(std::uint64_t afterSeq, std::uint8_t* out, std::uint32_t outLength) const
    {
        if (outLength < 16) return 0;
        const std::size_t fit{ (outLength - 16) / 24 };
        std::uint64_t missed{ 0 };
        std::vector<Event> events;
        {
            std::lock_guard<std::mutex> lock{ m_lock };
            events = readLocked(afterSeq, fit, missed);
        }
        const std::uint32_t count{ static_cast<std::uint32_t>(events.size()) };
        const std::uint32_t missed32{ static_cast<std::uint32_t>(std::min<std::uint64_t>(missed, 0xFFFFFFFFu)) };
        const std::uint64_t last{ events.empty() ? afterSeq : events.back().seq };
        std::memcpy(out, &count, 4);
        std::memcpy(out + 4, &missed32, 4);
        std::memcpy(out + 8, &last, 8);
        std::uint8_t* p{ out + 16 };
        for (const Event& e : events)
        {
            std::memcpy(p, &e.seq, 8); std::memcpy(p + 8, &e.time, 8); std::memcpy(p + 16, &e.pid, 4); std::memcpy(p + 20, &e.kind, 4);
            p += 24;
        }
        return 16 + count * 24;
    }

private:
    std::vector<Event> readLocked(std::uint64_t afterSeq, std::size_t maxCount, std::uint64_t& missed) const
    {
        std::vector<Event> out;
        missed = 0;
        if (m_count == 0) return out;
        const std::uint64_t oldestSeq{ m_lastSeq - m_count + 1 };
        if (oldestSeq > afterSeq + 1) missed = oldestSeq - afterSeq - 1;
        const std::size_t oldestSlot{ (m_next + m_slots.size() - m_count) % m_slots.size() };
        for (std::size_t i{ 0 }; i < m_count && out.size() < maxCount; ++i)
        {
            const Event& e{ m_slots[(oldestSlot + i) % m_slots.size()] };
            if (e.seq > afterSeq) out.push_back(e);
        }
        return out;
    }

    mutable std::mutex m_lock;
    std::vector<Event> m_slots;
    std::size_t m_next{ 0 }, m_count{ 0 };
    std::uint64_t m_lastSeq{ 0 }, m_overwritten{ 0 };
};

unitTests:
#include <cstring>
#include <thread>
std::vector<std::uint64_t> seqs(const std::vector<Event>& v) { std::vector<std::uint64_t> s; for (const auto& e : v) s.push_back(e.seq); return s; }
using Seqs = std::vector<std::uint64_t>;
TEST("filling and overwriting") {
    EventRing r{ 3 }; for (std::uint32_t i = 1; i <= 5; ++i) CHECK_EQ(r.push(i * 10, 100 + i, 1), std::uint64_t{ i });
    CHECK_EQ(r.size(), std::size_t{ 3 }); CHECK_EQ(r.overwritten(), std::uint64_t{ 2 });
    std::uint64_t missed = 99;
    CHECK_EQ(seqs(r.read(0, 10, missed)), (Seqs{ 3, 4, 5 })); CHECK_EQ(missed, std::uint64_t{ 2 });
    CHECK_EQ(seqs(r.read(3, 10, missed)), (Seqs{ 4, 5 })); CHECK_EQ(missed, std::uint64_t{ 0 });
    CHECK(r.read(5, 10, missed).empty()); CHECK_EQ(seqs(r.read(3, 1, missed)), (Seqs{ 4 })); CHECK_EQ(r.read(0, 10, missed)[0].pid, 103u);
}
TEST("empty ring") { EventRing r{ 4 }; std::uint64_t missed = 7; CHECK(r.read(0, 5, missed).empty()); CHECK_EQ(missed, std::uint64_t{ 0 }); }
TEST("the IOCTL format") {
    EventRing r{ 3 }; for (std::uint32_t i = 1; i <= 5; ++i) r.push(i * 10, 100 + i, i % 2);
    std::uint8_t out[64]{}; CHECK_EQ(r.serialize(0, out, 64), 64u);
    std::uint32_t count, missed; std::uint64_t last, seq, time; std::uint32_t pid, kind;
    std::memcpy(&count, out, 4); std::memcpy(&missed, out + 4, 4); std::memcpy(&last, out + 8, 8); CHECK_EQ(count, 2u); CHECK_EQ(missed, 2u); CHECK_EQ(last, std::uint64_t{ 4 });
    std::memcpy(&seq, out + 16, 8); std::memcpy(&time, out + 24, 8); std::memcpy(&pid, out + 32, 4); std::memcpy(&kind, out + 36, 4);
    CHECK_EQ(seq, std::uint64_t{ 3 }); CHECK_EQ(time, std::uint64_t{ 30 }); CHECK_EQ(pid, 103u); CHECK_EQ(kind, 1u);
    std::memcpy(&seq, out + 40, 8); CHECK_EQ(seq, std::uint64_t{ 4 });
    std::uint8_t next[100]{}; CHECK_EQ(r.serialize(last, next, 100), 40u); std::memcpy(&count, next, 4); CHECK_EQ(count, 1u);
    std::uint8_t none[30]{}; CHECK_EQ(r.serialize(5, none, 30), 16u); std::memcpy(&last, none + 8, 8); CHECK_EQ(last, std::uint64_t{ 5 });
    std::uint8_t tiny[15]{}; CHECK_EQ(r.serialize(0, tiny, 15), 0u);
}
TEST("many writers") {
    EventRing r{ 10000 }; std::vector<std::thread> t;
    for (int k = 0; k < 4; ++k) t.emplace_back([&r, k] { for (int i = 0; i < 1000; ++i) r.push(static_cast<std::uint64_t>(i), static_cast<std::uint32_t>(k), 0); });
    for (auto& x : t) x.join();
    std::uint64_t missed = 0; const auto all = r.read(0, 100000, missed);
    CHECK_EQ(all.size(), std::size_t{ 4000 }); CHECK_EQ(missed, std::uint64_t{ 0 });
    bool increasing = true; for (std::size_t i = 0; i < all.size(); ++i) increasing = increasing && all[i].seq == i + 1; CHECK(increasing);
}

